#!/usr/bin/env python3
# Automatic window widths/stacking that niri has no setting for (see its FAQ):
# - The first tiled window of a workspace opens full width, on every monitor.
# - Landscape monitors: when a second window opens, the first one goes back to half
#   width, so both sit side by side; from then on niri behaves as usual.
# - Portrait (rotated) monitors: every new window is stacked into the column on its
#   left, so windows pile up top to bottom instead of opening as new columns.
# Listens to the niri event stream. Started by spawn-at-startup in config.kdl; exits with niri.
import json
import subprocess


def niri(*args):
    return subprocess.run(["niri", "msg", *args], capture_output=True, text=True).stdout


def portrait_outputs():
    outputs = json.loads(niri("--json", "outputs"))
    return {name for name, o in outputs.items()
            if o.get("logical") and o["logical"]["height"] > o["logical"]["width"]}


workspaces = {}  # workspace id -> output name
windows = {}     # window id -> (workspace id, is floating)

stream = subprocess.Popen(["niri", "msg", "--json", "event-stream"],
                          stdout=subprocess.PIPE, text=True)
for line in stream.stdout:
    event = json.loads(line)
    if "WorkspacesChanged" in event:
        workspaces = {w["id"]: w["output"] for w in event["WorkspacesChanged"]["workspaces"]}
    elif "WindowsChanged" in event:
        # Initial list of windows (and full refreshes): never touched
        windows = {w["id"]: (w["workspace_id"], w["is_floating"])
                   for w in event["WindowsChanged"]["windows"]}
    elif "WindowOpenedOrChanged" in event:
        w = event["WindowOpenedOrChanged"]["window"]
        is_new = w["id"] not in windows
        windows[w["id"]] = (w["workspace_id"], w["is_floating"])
        if not is_new or w["is_floating"] or w["workspace_id"] is None:
            continue
        others = [i for i, (ws, fl) in windows.items()
                  if i != w["id"] and ws == w["workspace_id"] and not fl]
        if not others:
            # First window: full width, so the column fills the monitor
            niri("action", "set-window-width", "--id", str(w["id"]), "100%")
        elif workspaces.get(w["workspace_id"]) in portrait_outputs():
            # Stack under the focused column (new windows open to its right)
            niri("action", "consume-or-expel-window-left", "--id", str(w["id"]))
        elif len(others) == 1:
            # Second window on a landscape monitor: shrink the first one back to half
            # (the new one already opens at default-column-width, 50%)
            niri("action", "set-window-width", "--id", str(others[0]), "50%")
    elif "WindowClosed" in event:
        windows.pop(event["WindowClosed"]["id"], None)

